#### REQ-IFR-INT-001-001: AWS MSK Cluster Configuration

**Status**: Mandatory
**Rationale**: MSK is the primary event streaming platform for EaaS

**Requirements**:
- Provision MSK clusters using Kafka 3.6+ with KRaft mode (no ZooKeeper)
- Configure minimum 3 brokers across 3 AZs for HA
- Use m5.large instance type minimum (adjust based on workload)
- Enable auto-scaling for broker storage
- Configure retention policies: 7 days default, 30 days for critical topics

**Implementation**:
```hcl
module "msk_cluster" {
  source  = "terraform-aws-modules/msk-kafka-cluster/aws"
  version = "~> 2.0"

  name                   = "eaas-msk-${var.environment}"
  kafka_version          = "3.6.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type   = "kafka.m5.large"
    client_subnets  = var.private_subnet_ids
    storage_info {
      ebs_storage_info {
        volume_size            = 1000
        provisioned_throughput {
          enabled           = true
          volume_throughput = 250
        }
      }
    }
    security_groups = [aws_security_group.msk.id]
  }

  encryption_info {
    encryption_in_transit {
      client_broker = "TLS"
      in_cluster    = true
    }
    encryption_at_rest_kms_key_arn = aws_kms_key.msk.arn
  }

  client_authentication {
    sasl {
      iam = true
    }
  }

  configuration_info {
    arn      = aws_msk_configuration.kafka_config.arn
    revision = aws_msk_configuration.kafka_config.latest_revision
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk.name
      }
    }
  }

  tags = merge(var.common_tags, {
    Name        = "eaas-msk-${var.environment}"
    Environment = var.environment
    Component   = "event-broker"
  })
}

resource "aws_msk_configuration" "kafka_config" {
  name              = "eaas-msk-config-${var.environment}"
  kafka_versions    = ["3.6.0"]
  server_properties = <<PROPERTIES
auto.create.topics.enable=false
default.replication.factor=3
min.insync.replicas=2
log.retention.hours=168
log.retention.bytes=1073741824
compression.type=producer
max.message.bytes=1048576
PROPERTIES
}
```

