#### REQ-IFR-INT-001-002: IAM Authentication for MSK

**Status**: Mandatory
**Rationale**: Secure broker access using AWS IAM

**Requirements**:
- Enable IAM authentication for all MSK clusters
- Create IAM roles for application consumers and producers
- Implement least-privilege access policies per application
- Disable username/password authentication

**Implementation**:
```hcl
# IAM Role for Kafka Producers
resource "aws_iam_role" "msk_producer" {
  name = "eaas-msk-producer-${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "ecs-tasks.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_policy" "msk_producer" {
  name        = "eaas-msk-producer-policy-${var.environment}"
  description = "Policy for Kafka producers to write to MSK"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "kafka-cluster:Connect",
          "kafka-cluster:DescribeCluster"
        ]
        Resource = module.msk_cluster.arn
      },
      {
        Effect = "Allow"
        Action = [
          "kafka-cluster:WriteData",
          "kafka-cluster:DescribeTopic",
          "kafka-cluster:CreateTopic"
        ]
        Resource = "${module.msk_cluster.arn}/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_producer" {
  role       = aws_iam_role.msk_producer.name
  policy_arn = aws_iam_policy.msk_producer.arn
}

# IAM Role for Kafka Consumers
resource "aws_iam_role" "msk_consumer" {
  name = "eaas-msk-consumer-${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "ecs-tasks.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_policy" "msk_consumer" {
  name        = "eaas-msk-consumer-policy-${var.environment}"
  description = "Policy for Kafka consumers to read from MSK"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "kafka-cluster:Connect",
          "kafka-cluster:DescribeCluster"
        ]
        Resource = module.msk_cluster.arn
      },
      {
        Effect = "Allow"
        Action = [
          "kafka-cluster:ReadData",
          "kafka-cluster:DescribeTopic",
          "kafka-cluster:DescribeGroup"
        ]
        Resource = "${module.msk_cluster.arn}/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_consumer" {
  role       = aws_iam_role.msk_consumer.name
  policy_arn = aws_iam_policy.msk_consumer.arn
}
```

