#### REQ-IFR-INT-001-003: TLS Encryption Configuration

**Status**: Mandatory
**Rationale**: Encrypt data in transit and at rest

**Requirements**:
- Enable TLS 1.2+ for client-broker communication
- Enable encryption at rest using AWS KMS
- Configure TLS certificates for broker communication
- Enforce TLS for all client connections

**Implementation**:
```hcl
# KMS Key for MSK Encryption
resource "aws_kms_key" "msk" {
  description             = "KMS key for MSK cluster encryption - ${var.environment}"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(var.common_tags, {
    Name        = "eaas-msk-kms-${var.environment}"
    Component   = "event-broker"
  })
}

resource "aws_kms_alias" "msk" {
  name          = "alias/eaas-msk-${var.environment}"
  target_key_id = aws_kms_key.msk.key_id
}

resource "aws_kms_key_policy" "msk" {
  key_id = aws_kms_key.msk.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow MSK to use the key"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:CreateGrant"
        ]
        Resource = "*"
      }
    ]
  })
}

# ACM Private CA for mTLS (Optional)
resource "aws_acmpca_certificate_authority" "msk" {
  count = var.enable_mtls ? 1 : 0

  type = "ROOT"

  certificate_authority_configuration {
    key_algorithm     = "RSA_4096"
    signing_algorithm = "SHA512WITHRSA"

    subject {
      common_name = "msk.${var.environment}.internal"
      organization = "Enterprise Architecture"
    }
  }

  permanent_deletion_time_in_days = 7

  tags = merge(var.common_tags, {
    Name = "eaas-msk-ca-${var.environment}"
  })
}
```

