#### REQ-IFR-INT-001-005: Amazon MQ Broker Configuration

**Status**: Mandatory
**Rationale**: RabbitMQ/ActiveMQ for specific integration patterns

**Requirements**:
- Provision Amazon MQ brokers (RabbitMQ 3.12+ or ActiveMQ 5.17+)
- Configure active/standby deployment for HA
- Enable audit logging to CloudWatch
- Configure broker storage: minimum 50 GB EBS

**Implementation**:
```hcl
resource "aws_mq_broker" "rabbitmq" {
  broker_name        = "eaas-mq-${var.environment}"
  engine_type        = "RabbitMQ"
  engine_version     = "3.12.13"
  host_instance_type = "mq.m5.large"
  deployment_mode    = "CLUSTER_MULTI_AZ"

  user {
    username = var.mq_admin_username
    password = aws_secretsmanager_secret_version.mq_password.secret_string
  }

  subnet_ids         = var.private_subnet_ids
  security_groups    = [aws_security_group.mq.id]
  publicly_accessible = false

  encryption_options {
    use_aws_owned_key = false
    kms_key_id        = aws_kms_key.mq.arn
  }

  logs {
    general = true
    audit   = var.enable_audit_logs
  }

  maintenance_window_start_time {
    day_of_week = "SUNDAY"
    time_of_day = "03:00"
    time_zone   = "UTC"
  }

  storage_type = "ebs"

  tags = merge(var.common_tags, {
    Name        = "eaas-mq-${var.environment}"
    Environment = var.environment
    Component   = "message-broker"
  })
}

resource "aws_security_group" "mq" {
  name_prefix = "eaas-mq-${var.environment}-"
  description = "Security group for Amazon MQ broker"
  vpc_id      = var.vpc_id

  ingress {
    description = "AMQP"
    from_port   = 5671
    to_port     = 5671
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  ingress {
    description = "RabbitMQ Management Console"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(var.common_tags, {
    Name = "eaas-mq-sg-${var.environment}"
  })
}

resource "aws_kms_key" "mq" {
  description             = "KMS key for Amazon MQ encryption - ${var.environment}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}
```

