#### REQ-IFR-INT-001-009: Disaster Recovery Configuration

**Status**: Mandatory
**Rationale**: Meet 4-hour RPO for critical event data

**Requirements**:
- Configure cross-region MirrorMaker 2.0 replication for critical topics
- Implement automated backups for broker configurations
- Document DR runbooks and test quarterly
- Configure disaster recovery to secondary AWS region

**Implementation**:
```hcl
# MirrorMaker 2.0 for Cross-Region Replication
resource "aws_ecs_task_definition" "mirrormaker" {
  family                   = "eaas-mirrormaker-${var.environment}"
  requires_compatibilities = ["FARGATE"]
  network_mode            = "awsvpc"
  cpu                     = 2048
  memory                  = 4096
  execution_role_arn      = aws_iam_role.ecs_execution.arn
  task_role_arn           = aws_iam_role.mirrormaker.arn

  container_definitions = jsonencode([{
    name  = "mirrormaker"
    image = "confluentinc/cp-kafka:7.5.0"
    command = [
      "/bin/connect-mirror-maker",
      "/etc/kafka/mm2.properties"
    ]

    environment = [
      {name = "KAFKA_HEAP_OPTS", value = "-Xms2g -Xmx2g"},
      {name = "SOURCE_CLUSTER", value = module.msk_cluster.bootstrap_brokers_tls},
      {name = "TARGET_CLUSTER", value = var.dr_cluster_bootstrap_servers}
    ]

    secrets = [
      {name = "MM2_CONFIG", valueFrom = aws_secretsmanager_secret.mm2_config.arn}
    ]

    logConfiguration = {
      logDriver = "awslogs"
      options = {
        "awslogs-group"         = aws_cloudwatch_log_group.mirrormaker.name
        "awslogs-region"        = var.aws_region
        "awslogs-stream-prefix" = "mm2"
      }
    }
  }])

  tags = merge(var.common_tags, {
    Name = "eaas-mirrormaker-${var.environment}"
  })
}

resource "aws_ecs_service" "mirrormaker" {
  name            = "eaas-mirrormaker-${var.environment}"
  cluster         = var.ecs_cluster_id
  task_definition = aws_ecs_task_definition.mirrormaker.arn
  desired_count   = 2
  launch_type     = "FARGATE"

  network_configuration {
    subnets          = var.private_subnet_ids
    security_groups  = [aws_security_group.mirrormaker.id]
    assign_public_ip = false
  }
}

# Automated Configuration Backup
resource "aws_backup_plan" "broker_config" {
  name = "eaas-broker-config-backup-${var.environment}"

  rule {
    rule_name         = "daily_backup"
    target_vault_name = aws_backup_vault.broker.name
    schedule          = "cron(0 2 * * ? *)"

    lifecycle {
      delete_after = 30
    }
  }

  rule {
    rule_name         = "weekly_backup"
    target_vault_name = aws_backup_vault.broker.name
    schedule          = "cron(0 2 ? * 1 *)"

    lifecycle {
      cold_storage_after = 30
      delete_after       = 90
    }
  }
}

resource "aws_backup_vault" "broker" {
  name        = "eaas-broker-backup-${var.environment}"
  kms_key_arn = aws_kms_key.backup.arn
}

# Lambda for DR Configuration Export
resource "aws_lambda_function" "config_backup" {
  filename      = "config_backup.zip"
  function_name = "eaas-broker-config-backup-${var.environment}"
  role          = aws_iam_role.lambda_backup.arn
  handler       = "index.handler"
  runtime       = "python3.11"
  timeout       = 300

  environment {
    variables = {
      MSK_CLUSTER_ARN = module.msk_cluster.arn
      S3_BUCKET       = aws_s3_bucket.dr_configs.id
    }
  }
}

resource "aws_cloudwatch_event_rule" "daily_backup" {
  name                = "eaas-broker-config-backup-${var.environment}"
  description         = "Trigger daily configuration backup"
  schedule_expression = "cron(0 3 * * ? *)"
}

resource "aws_cloudwatch_event_target" "lambda" {
  rule      = aws_cloudwatch_event_rule.daily_backup.name
  target_id = "ConfigBackupLambda"
  arn       = aws_lambda_function.config_backup.arn
}
```

