### Amazon MQ Broker Provisioning Template

```hcl
# Example: Amazon MQ RabbitMQ Cluster for Legacy Integration
# File: environments/production/mq.tf

resource "aws_secretsmanager_secret" "mq_password" {
  name_prefix             = "eaas-mq-password-"
  recovery_window_in_days = 7
}

resource "aws_secretsmanager_secret_version" "mq_password" {
  secret_id     = aws_secretsmanager_secret.mq_password.id
  secret_string = random_password.mq_admin.result
}

resource "random_password" "mq_admin" {
  length  = 32
  special = true
}

resource "aws_mq_broker" "production_rabbitmq" {
  broker_name             = "eaas-mq-production"
  engine_type             = "RabbitMQ"
  engine_version          = "3.12.13"
  host_instance_type      = "mq.m5.large"
  deployment_mode         = "CLUSTER_MULTI_AZ"
  storage_type            = "ebs"
  publicly_accessible     = false
  auto_minor_version_upgrade = true

  user {
    username       = "admin"
    password       = aws_secretsmanager_secret_version.mq_password.secret_string
    console_access = true
    groups         = ["administrators"]
  }

  subnet_ids      = data.aws_subnets.private.ids
  security_groups = [aws_security_group.mq.id]

  encryption_options {
    use_aws_owned_key = false
    kms_key_id        = aws_kms_key.mq.arn
  }

  logs {
    general = true
    audit   = true
  }

  maintenance_window_start_time {
    day_of_week = "SUNDAY"
    time_of_day = "03:00"
    time_zone   = "UTC"
  }

  tags = {
    Name          = "eaas-mq-production"
    Environment   = "production"
    Component     = "message-broker"
    CostCenter    = "ENG-001"
    BusinessUnit  = "Platform Engineering"
  }
}

output "mq_console_url" {
  value = "https://${aws_mq_broker.production_rabbitmq.instances[0].console_url}"
}

output "mq_amqps_endpoint" {
  value = "amqps://${aws_mq_broker.production_rabbitmq.instances[0].endpoints[0]}"
}
```
